    /**
     * @method
     * @name interactivebrokers#signIn
     * @description obtains a live session token via the oauth 1.0a diffie-hellman exchange and opens the brokerage session, must be called prior to using other authenticated methods (called automatically by authenticate)
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/authentication/oauth-1-0-a/req-live-session-token
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/initialize-session
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} response from the exchange
     */
    public async override Task<object> signIn(IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.safeBool(this.options, "useGateway", false) == true))
        {
            return await this.ibkrGatewaySignIn(parameters);
        }
        string? encryptionPemPath = this.safeString(this.options, "encryptionPemPath", "");
        string? dhParamPemPath = this.safeString(this.options, "dhParamPemPath", "");
        if ((encryptionPemPath == "") || (dhParamPemPath == ""))
        {
            throw new ArgumentsRequired ((this.id + " supports two different authentication methods. You can either use the gateway or oauth 1.0 (if your account allows it) by providing encryptionPemPath and dhParamPemPath in options. Please check the FAQ for more details")) ;
        }
        this.ibkrCheckOauthCredentials();
        await this.initFileSystem();
        string encryptionKey = ((string)this.readFile(encryptionPemPath));
        object dhPrime = this.convertToBigInt(("0x" + (this.readDhParam(dhParamPemPath))));
        // the access token secret is encrypted with the consumer's public encryption key
        byte[] decrypted = this.decryptPrivateKey(encryptionKey, this.secret);
        object accessTokenSecretHex = this.binaryToBase16(decrypted);
        this.options["accessTokenSecretHex"] = accessTokenSecretHex; // prepended to the signature base string in sign ()
        this.options["serviceAccountsLoaded"] = false; // a new brokerage session needs iserver/accounts again
        object dhRandom = this.convertToBigInt(("0x" + this.randomBytes(32)));
        System.Numerics.BigInteger dhChallenge = this.modPow((this.options != null && this.options.ContainsKey("dhGen") ? this.options["dhGen"] : null), dhRandom, dhPrime);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "diffie_hellman_challenge", this.intToBase16(dhChallenge) },
        };
        Dictionary<string, object> response = await this.webapiPostV1ApiOauthLiveSessionToken(this.extend(request, parameters));
        //
        //     {
        //         "diffie_hellman_response": "1d9c...",
        //         "live_session_token_signature": "9a7e...",
        //         "live_session_token_expiration": 1714661586311
        //     }
        //
        string? dhResponse = this.safeString(response, "diffie_hellman_response", "");
        System.Numerics.BigInteger sharedSecret = this.modPow(this.convertToBigInt(("0x" + dhResponse)), dhRandom, dhPrime);
        string liveSessionToken = this.hmac(this.base16ToBinary(accessTokenSecretHex), this.bigToBytes(sharedSecret), sha1, "base64");
        string? consumerKey = this.safeString(this.options, "consumer_key", "");
        string check = this.hmac(consumerKey, this.base64ToBinary(liveSessionToken), sha1, "hex");
        if ((check != this.safeString(response, "live_session_token_signature")))
        {
            throw new AuthenticationError ((this.id + " signIn() live session token validation failed")) ;
        }
        this.options["liveSessionToken"] = liveSessionToken;
        this.options["liveSessionTokenExpiration"] = this.safeInteger(response, "live_session_token_expiration");
        // open the brokerage session
        IDictionary<string, object> initRequest = this.safeDict(this.options, "signInInitRequest", new Dictionary<string, object>() {});
        await this.webapiPostV1ApiIserverAuthSsodhInit(initRequest);
        await this.fetchServiceAccounts();
        return response;
    }

    /**
     * @method
     * @name interactivebrokers#authenticate
     * @description signs in when there is no live session token yet or the current one is about to expire
     * @ignore
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {string} the live session token
     */
    public async virtual Task<string?> authenticate(IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if (this.ibkrIsAuthenticated())
        {
            return this.safeString(this.options, "liveSessionToken");
        }
        // single-flight, see https://github.com/ccxt/ccxt/issues/29393
        // concurrent private calls on a cold (or expiring) instance would each pass the staleness
        // gate above and each run their own signIn (), so the first caller signs in and the rest
        // wait for it to finish, then reuse its token (or sign in themselves if the leader failed)
        if ((this.safeBool(this.options, "signInInProgress", false) == true))
        {
            Int64? pollInterval = this.safeInteger(this.options, "signInPollInterval", 100);
            Int64? maxWait = this.safeInteger(this.options, "signInMaxWait", 60000);
            Int64 waited = 0;
            while ((this.safeBool(this.options, "signInInProgress", false) == true) && ((waited < maxWait)))
            {
                await this.sleep(pollInterval);
                waited = this.sum(waited, pollInterval);
            }
            if (this.ibkrIsAuthenticated())
            {
                return this.safeString(this.options, "liveSessionToken");
            }
        }
        this.options["signInInProgress"] = true;
        try
        {
            await this.signIn(parameters);
        } catch(Exception e)
        {
            this.options["signInInProgress"] = false;
            throw e;
        }
        this.options["signInInProgress"] = false;
        return this.safeString(this.options, "liveSessionToken");
    }

    /**
     * @method
     * @name interactivebrokers#ibkrIsAuthenticated
     * @description true when the current session can be used without signing in again, with options.useGateway the gateway session was confirmed authenticated within options.gatewayAuthCheckInterval ms, otherwise the oauth live session token is fresh
     * @ignore
     * @returns {boolean} whether the current session can be used
     */
    public virtual bool ibkrIsAuthenticated()
    {
        if (!(this.safeBool(this.options, "useGateway", false) == true))
        {
            return this.ibkrHasFreshSessionToken();
        }
        Int64? authenticatedTimestamp = this.safeInteger(this.options, "gatewayAuthenticatedTimestamp");
        if ((authenticatedTimestamp == null))
        {
            return false;
        }
        Int64? checkInterval = this.safeInteger(this.options, "gatewayAuthCheckInterval", 120000);
        return (this.milliseconds() < this.sum(authenticatedTimestamp, checkInterval));
    }

    /**
     * @method
     * @name interactivebrokers#ibkrGatewaySignIn
     * @description checks that the client portal gateway session is authenticated (taking the brokerage session back via ssodh/init options.autoRegainSession seconds after it was lost), loads the trading accounts and starts the keep-alive loop
     * @ignore
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/get-brokerage-status
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/initialize-session
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} the iserver/auth/status response
     */
    public async virtual Task<Dictionary<string, object>> ibkrGatewaySignIn(IDictionary<string, object>? parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> response = await this.webapiPostV1ApiIserverAuthStatus(parameters);
        //
        //     {
        //         "authenticated": true,
        //         "established": true,
        //         "competing": false,
        //         "connected": true,
        //         "message": "",
        //         "MAC": "06:A5:C8:3D:7F:EC",
        //         "serverInfo": { "serverName": "JifZ18024", "serverVersion": "Build 10.50.1e, Oct 26, 2026 5:04:19 PM" },
        //         "hardware_info": "6b0d051e|06:A5:C8:3D:7F:EC",
        //         "fail": ""
        //     }
        //
        bool? authenticated = this.safeBool(response, "authenticated", false);
        bool? established = this.safeBool(this.options, "gatewaySessionEstablished", false);
        bool? openOnStart = this.safeBool(this.options, "gatewayReauthenticate", true);
        if (authenticated != true && established != true && (openOnStart == true))
        {
            // the first sign in of this instance opens the brokerage session right away
            response = await this.ibkrGatewayRegainSession(parameters);
            authenticated = this.safeBool(response, "authenticated", false);
            if (authenticated != true)
            {
                string gatewayUrl = this.safeString(this.options, "gatewayUrl");
                throw new AuthenticationError (((((this.id + " the client portal gateway session is not authenticated, log in at ") + gatewayUrl) + " in a browser, ") + this.json(response))) ;
            }
        }
        if (authenticated != true)
        {
            // the sso login is alive but the brokerage session is not (e.g. taken over by a login with the same username elsewhere, or after the daily reset)
            Int64? lostTimestamp = this.ibkrGatewayOnSessionLost();
            Int64? regainDelay = this.ibkrGatewayRegainDelay();
            if ((regainDelay == null || regainDelay <= 0))
            {
                string gatewayUrl = this.safeString(this.options, "gatewayUrl");
                throw new AuthenticationError (((((this.id + " the brokerage session of the client portal gateway is not authenticated (e.g. it was taken over by a login with the same username elsewhere), log in again at ") + gatewayUrl) + " in a browser or set options.autoRegainSession to take it back automatically, ") + this.json(response))) ;
            }
            Int64 regainTimestamp = this.sum(lostTimestamp, regainDelay);
            if (this.milliseconds() < regainTimestamp)
            {
                string? regainDatetime = this.iso8601(regainTimestamp);
                throw new AuthenticationError (((((this.id + " the brokerage session of the client portal gateway is not authenticated (e.g. it was taken over by a login with the same username elsewhere), it will be taken back at ") + regainDatetime) + " (options.autoRegainSession), ") + this.json(response))) ;
            }
            response = await this.ibkrGatewayRegainSession(parameters);
            authenticated = this.safeBool(response, "authenticated", false);
            if (authenticated != true)
            {
                // try again options.autoRegainSession seconds later
                this.options["gatewaySessionLostTimestamp"] = this.milliseconds();
                this.ibkrGatewayScheduleRegain();
                string? retryDatetime = this.iso8601(this.sum(this.milliseconds(), regainDelay));
                throw new AuthenticationError (((((this.id + " failed to take back the brokerage session of the client portal gateway, retrying at ") + retryDatetime) + " (options.autoRegainSession), ") + this.json(response))) ;
            }
        }
        this.options["gatewaySessionLostTimestamp"] = null;
        this.options["serviceAccountsLoaded"] = false;
        await this.fetchServiceAccounts();
        this.options["gatewaySessionEstablished"] = true;
        this.options["gatewayAuthenticatedTimestamp"] = this.milliseconds();
        this.ibkrGatewayStartKeepAlive();
        return response;
    }

    /**
     * @method
     * @name interactivebrokers#ibkrGatewayRegainSession
     * @description opens the brokerage session of the client portal gateway with POST iserver/auth/ssodh/init (taking it over from any other login with the same username) and polls iserver/auth/status until it is authenticated
     * @ignore
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/initialize-session
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} the last iserver/auth/status response
     */
    public async virtual Task<Dictionary<string, object>> ibkrGatewayRegainSession(IDictionary<string, object>? parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        IDictionary<string, object> initRequest = this.safeDict(this.options, "signInInitRequest", new Dictionary<string, object>() {});
        await this.webapiPostV1ApiIserverAuthSsodhInit(initRequest);
        Int64? retries = this.safeInteger(this.options, "gatewayReauthenticateRetries", 5);
        Int64? retryDelay = this.safeInteger(this.options, "gatewayReauthenticateDelay", 1000);
        Dictionary<string, object> response = new Dictionary<string, object>() {};
        for (int i = 0; i < retries.GetValueOrDefault(); i++)
        {
            await this.sleep(retryDelay);
            response = await this.webapiPostV1ApiIserverAuthStatus(parameters);
            if ((this.safeBool(response, "authenticated", false) == true))
            {
                break;
            }
        }
        return response;
    }

    /**
     * @method
     * @name interactivebrokers#ibkrGatewayRegainDelay
     * @description options.autoRegainSession in milliseconds, 0 when the lost brokerage session must not be taken back
     * @ignore
     * @returns {int} the delay in milliseconds
     */
    public virtual Int64? ibkrGatewayRegainDelay()
    {
        double? seconds = this.safeNumber(this.options, "autoRegainSession", 0);
        if (((seconds == null)) || ((!(seconds > 0))))
        {
            return 0;
        }
        return this.parseToInt(((double?)seconds * 1000));
    }

    /**
     * @method
     * @name interactivebrokers#ibkrGatewayOnSessionLost
     * @description marks the brokerage session as lost and schedules taking it back, see options.autoRegainSession
     * @ignore
     * @returns {int} the timestamp when the session was found lost
     */
    public virtual Int64? ibkrGatewayOnSessionLost()
    {
        this.options["gatewayAuthenticatedTimestamp"] = null;
        Int64? lostTimestamp = this.milliseconds();
        Int64? storedTimestamp = this.safeInteger(this.options, "gatewaySessionLostTimestamp");
        if ((storedTimestamp == null))
        {
            this.options["gatewaySessionLostTimestamp"] = lostTimestamp;
            this.ibkrGatewayScheduleRegain();
        } else
        {
            lostTimestamp = storedTimestamp;
        }
        return lostTimestamp;
    }

    /**
     * @method
     * @name interactivebrokers#ibkrGatewayScheduleRegain
     * @description schedules taking the lost brokerage session back options.autoRegainSession seconds after it was lost, so it is regained even when no private calls are made, the synchronous python and php versions take it back on the next private call instead
     * @ignore
     * @returns {boolean} true if it was scheduled
     */
    public virtual bool ibkrGatewayScheduleRegain()
    {
        Int64? regainDelay = this.ibkrGatewayRegainDelay();
        if (((regainDelay == null || regainDelay <= 0)) || (this.safeBool(this.options, "gatewayRegainScheduled", false) == true))
        {
            return false;
        }
        Int64? lostTimestamp = this.safeInteger(this.options, "gatewaySessionLostTimestamp", this.milliseconds());
        Int64? wait = (this.sum(lostTimestamp, regainDelay) - this.milliseconds());
        if ((wait == null || wait <= 0))
        {
            wait = regainDelay;
        }
        try
        {
            this.delay(wait, this.ibkrGatewayRegainLoop);
            this.options["gatewayRegainScheduled"] = true;
        } catch(Exception e)
        {
            this.options["gatewayRegainScheduled"] = false;
            return false;
        }
        return true;
    }

    /**
     * @method
     * @name interactivebrokers#ibkrGatewayRegainLoop
     * @description takes the lost brokerage session back, rescheduled every options.autoRegainSession seconds until it succeeds, stops when it is set to 0 or the instance is closed
     * @ignore
     * @returns {undefined}
     */
    public async virtual Task<object> ibkrGatewayRegainLoop()
    {
        this.options["gatewayRegainScheduled"] = false;
        bool? useGateway = this.safeBool(this.options, "useGateway", false);
        Int64? lostTimestamp = this.safeInteger(this.options, "gatewaySessionLostTimestamp");
        Int64? regainDelay = this.ibkrGatewayRegainDelay();
        if (useGateway != true || ((lostTimestamp == null)) || ((regainDelay == null || regainDelay <= 0)))
        {
            return null;  // already regained, or disabled
        }
        try
        {
            await this.authenticate();
        } catch(Exception e)
        {
            if (e is ExchangeClosedByUser)
            {
                return null;
            }
            if (this.verbose)
            {
                this.log(("ibkrGatewayRegainLoop failed " + (this.exceptionMessage(e))));
            }
            // e.g. the sso login is lost too (http 401), retry until it is logged in again at options.gatewayUrl
            if (!(this.safeInteger(this.options, "gatewaySessionLostTimestamp") == null))
            {
                this.ibkrGatewayScheduleRegain();
            }
        }
        return null;
    }

    /**
     * @method
     * @name interactivebrokers#ibkrGatewayStartKeepAlive
     * @description schedules the keep-alive loop once, see options.gatewayKeepAlive
     * @ignore
     * @returns {boolean} true if the loop is running
     */
    public virtual bool ibkrGatewayStartKeepAlive()
    {
        bool? keepAlive = this.safeBool(this.options, "gatewayKeepAlive", true);
        if (keepAlive != true || (this.safeBool(this.options, "gatewayKeepAliveStarted", false) == true))
        {
            return ((bool)((object)(keepAlive))!);
        }
        Int64? interval = this.safeInteger(this.options, "gatewayKeepAliveInterval", 60000);
        try
        {
            this.delay(interval, this.ibkrGatewayKeepAlive);
            this.options["gatewayKeepAliveStarted"] = true;
        } catch(Exception e)
        {
            // the synchronous python and php versions have no event loop to schedule on, the session is
            // then kept alive by the private calls, which re-check iserver/auth/status every gatewayAuthCheckInterval ms
            this.options["gatewayKeepAliveStarted"] = false;
            return false;
        }
        return true;
    }

    /**
     * @method
     * @name interactivebrokers#ibkrGatewayKeepAlive
     * @description keeps the client portal gateway session alive with POST /tickle every options.gatewayKeepAliveInterval ms and tracks its authentication status, stops when options.gatewayKeepAlive is set to false or the instance is closed
     * @ignore
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/get-session-token
     * @returns {undefined}
     */
    public async virtual Task<object> ibkrGatewayKeepAlive()
    {
        bool? useGateway = this.safeBool(this.options, "useGateway", false);
        bool? keepAlive = this.safeBool(this.options, "gatewayKeepAlive", true);
        if (useGateway != true || keepAlive != true)
        {
            this.options["gatewayKeepAliveStarted"] = false;
            return null;
        }
        try
        {
            Dictionary<string, object> response = await this.webapiPostV1ApiTickle();
            //
            //     {
            //         "session": "dcbd01d969bfd9434139f372edc338b2",
            //         "ssoExpires": 237821,
            //         "collission": false,
            //         "userId": 46130428,
            //         "hmds": { "error": "no bridge" },
            //         "iserver": { "authStatus": { "authenticated": true, "established": true, "competing": false, "connected": true, ... } }
            //     }
            //
            IDictionary<string, object> iserver = this.safeDict(response, "iserver", new Dictionary<string, object>() {});
            IDictionary<string, object> authStatus = this.safeDict(iserver, "authStatus", new Dictionary<string, object>() {});
            if ((this.safeBool(authStatus, "authenticated", false) == true))
            {
                if ((this.safeInteger(this.options, "gatewaySessionLostTimestamp") == null))
                {
                    this.options["gatewayAuthenticatedTimestamp"] = this.milliseconds();
                }
            } else
            {
                // e.g. taken over by a login with the same username elsewhere, see options.autoRegainSession
                this.ibkrGatewayOnSessionLost();
            }
        } catch(Exception e)
        {
            if (e is ExchangeClosedByUser)
            {
                this.options["gatewayKeepAliveStarted"] = false;
                return null;
            }
            // a failing tickle (e.g. the gateway container restarts) is retried on the next interval
            this.options["gatewayAuthenticatedTimestamp"] = null;
            if (this.verbose)
            {
                this.log(("ibkrGatewayKeepAlive tickle failed " + (this.exceptionMessage(e))));
            }
        }
        Int64? interval = this.safeInteger(this.options, "gatewayKeepAliveInterval", 60000);
        this.delay(interval, this.ibkrGatewayKeepAlive);
        return null;
    }

    /**
     * @method
     * @name interactivebrokers#ibkrHasFreshSessionToken
     * @description true when a live session token is set and is not about to expire
     * @ignore
     * @returns {boolean} whether the current live session token can be used
     */
    public virtual bool ibkrHasFreshSessionToken()
    {
        string? liveSessionToken = this.safeString(this.options, "liveSessionToken");
        if ((liveSessionToken == null))
        {
            return false;
        }
        Int64? expiration = this.safeInteger(this.options, "liveSessionTokenExpiration");
        if ((expiration == null))
        {
            return true;
        }
        Int64? refreshMargin = this.safeInteger(this.options, "liveSessionTokenRefreshMargin", 60000);
        return (this.sum(this.milliseconds(), refreshMargin) < expiration);
    }

    /**
     * @method
     * @name interactivebrokers#loadAccountId
     * @description returns the account id from params, options, or the first account returned by fetchAccounts
     * @ignore
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.accountId] the account id to use
     * @returns {Array} the account id and the params without accountId
     */
    public async virtual Task<object> loadAccountId(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        (string?, IDictionary<string, object>) accountIdFromParamsqueryVariable = this.handleOptionStringAndParams(parameters, "loadAccountId", "accountId");
        string? accountIdFromParams = accountIdFromParamsqueryVariable.Item1;
        IDictionary<string, object> query = (accountIdFromParamsqueryVariable.Item2);
        string? accountId = accountIdFromParams;
        if ((accountId == null))
        {
            ccxt.BaseExchange.FromAccountList(await this.FetchAccounts());
            accountId = this.safeString(this.options, "accountId");
        }
        if ((accountId == null))
        {
            throw new ArgumentsRequired ((this.id + " requires an accountId in params[\"accountId\"] or options[\"accountId\"], fetchAccounts() returned no accounts")) ;
        }
        return new List<object>() {accountId, query};
    }

    /**
     * @method
     * @name interactivebrokers#fetchBalance
     * @description query for balance and get the amount of funds available for trading or funds locked in orders, the cash comes from the ledger, the crypto holdings from the positions and the locked ('used') amounts from the open orders of the current brokerage session
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-portfolio-ledger
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-uncached-positions
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/get-open-orders
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.accountId] the account id, defaults to options["accountId"] or the selected account
     * @param {boolean} [params.positions] add the holdings of options.fetchBalance.positionAssetClasses (crypto by default) as balances, default true
     * @param {boolean} [params.openOrders] compute the locked ('used') amounts from the open orders, default true
     * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
     */
    public async override Task<ccxt.Balances> FetchBalance(IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.authenticate();
        var accountIdaccountQueryVariable = await this.loadAccountId(parameters);
        var accountId = ((IList<object>) accountIdaccountQueryVariable)[0];
        var accountQuery = ((IList<object>) accountIdaccountQueryVariable)[1];
        Dictionary<string, object> accountParams = this.extend(new Dictionary<string, object>() {}, accountQuery);
        (bool?, IDictionary<string, object>) withPositionspositionsQueryVariable = this.handleOptionBoolAndParams(accountParams, "fetchBalance", "positions", true);
        bool? withPositions = withPositionspositionsQueryVariable.Item1;
        IDictionary<string, object> positionsQuery = (withPositionspositionsQueryVariable.Item2);
        (bool?, IDictionary<string, object>) withOpenOrdersqueryVariable = this.handleOptionBoolAndParams(positionsQuery, "fetchBalance", "openOrders", true);
        bool? withOpenOrders = withOpenOrdersqueryVariable.Item1;
        IDictionary<string, object> query = (withOpenOrdersqueryVariable.Item2);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "accountId", accountId },
        };
        if ((withPositions == true) || (withOpenOrders == true))
        {
            // the conids of the positions and orders are resolved to currencies via the markets
            if ((this.markets == null))
            {
                await this.loadMarkets();
            }
        }
        List<object> promises = new List<object>() {};
        promises.Add(this.webapiGetV1ApiPortfolioAccountIdLedger(this.extend(request, query)));
        if ((withPositions == true))
        {
            promises.Add(this.webapiGetV1ApiPortfolio2AccountIdPositions(request));
        }
        if ((withOpenOrders == true))
        {
            promises.Add(this.fetchLiveOrdersRaw());
        }
        List<object> results = await promiseAll(promises);
        IDictionary<string, object> response = this.safeDict(results, 0, new Dictionary<string, object>() {});
        //
        //     {
        //         "USD": {
        //             "commoditymarketvalue": 0.0,
        //             "futuremarketvalue": 0.0,
        //             "settledcash": 214716688.0,
        //             "exchangerate": 1,
        //             "sessionid": 1,
        //             "cashbalance": 214716688.0,
        //             "corporatebondsmarketvalue": 0.0,
        //             "netliquidationvalue": 215335840.0,
        //             "interest": 305569.94,
        //             "unrealizedpnl": 39695.82,
        //             "stockmarketvalue": 314123.88,
        //             "currency": "USD",
        //             "realizedpnl": 0.0,
        //             "acctcode": "U1234567",
        //             "key": "LedgerList",
        //             "timestamp": 1702582321,
        //             "secondkey": "USD",
        //             ...
        //         },
        //         "BASE": { ... }
        //     }
        //
        Dictionary<string, object> balanceResponse = new Dictionary<string, object>() {
            { "ledger", response },
        };
        Int64 index = 1;
        if ((withPositions == true))
        {
            balanceResponse["positions"] = this.safeList(results, index);
            index = (index + 1);
        }
        if ((withOpenOrders == true))
        {
            // the 'orders' key is present only when the open orders were fetched, then the currencies without open orders get used = 0
            balanceResponse["orders"] = this.safeList(results, index);
        }
        return ccxt.BaseExchange.ToBalances(this.parseBalance(balanceResponse));
    }

    public override Dictionary<string, object> parseBalance(IDictionary<string, object> response)
    {
        //
        //     {
        //         "ledger": { "USD": { "cashbalance": 1000.0, ... }, "BASE": { "timestamp": 1702582321, ... } },
        //         "positions": [ { "position": 0.04, "conid": "495759171", "description": "ETH CRYPTO", "secType": "CRYPTO", ... } ],
        //         "orders": [ { "conid": 479624278, "side": "BUY", "status": "Submitted", "price": "80000", "remainingQuantity": 0.001, "cashCcy": "USD", ... } ]
        //     }
        //
        IDictionary<string, object> ledger = this.safeDict(response, "ledger", response);
        List<object> positions = this.safeList(response, "positions", new List<object>() {});
        List<object> orders = this.safeList(response, "orders", new List<object>() {});
        Dictionary<string, object> result = new Dictionary<string, object>() {
            { "info", response },
        };
        // cash, from the ledger
        List<object> currencyIds = new List<object>(ledger.Keys);
        for (int i = 0; i < currencyIds.Count; i++)
        {
            string? currencyId = ((string)currencyIds[i]);
            if (currencyId == "BASE")
            {
                continue;
            }
            IDictionary<string, object> balance = this.safeDict(ledger, currencyId);
            if ((balance == null))
            {
                continue;
            }
            string code = this.safeCurrencyCode(currencyId);
            Dictionary<string, object> account = this.account();
            account["total"] = this.safeString(balance, "cashbalance");
            result[(string)code] = account;
        }
        // holdings, from the positions
        IDictionary<string, object> balanceOptions = this.safeDict(this.options, "fetchBalance", new Dictionary<string, object>() {});
        List<object> positionAssetClasses = this.safeList(balanceOptions, "positionAssetClasses", new List<object>() {"CRYPTO"});
        for (int i = 0; i < positions.Count; i++)
        {
            object position = positions[i];
            // portfolio2 positions have "secType", the cached portfolio positions have "assetClass"
            string? assetClass = this.safeString2(position, "secType", "assetClass");
            if (!this.inArray(assetClass, positionAssetClasses))
            {
                continue;
            }
            string? code = this.ibkrBalanceCode(position);
            if (((code == null)) || ((result != null && code != null && result.ContainsKey(code))))
            {
                continue;
            }
            Dictionary<string, object> account = this.account();
            account["total"] = this.safeString(position, "position");
            result[(string)code] = account;
        }
        // locked amounts, from the open orders: buy orders lock remaining * price of the quote currency, sell orders lock the remaining base amount
        Dictionary<string, object> used = new Dictionary<string, object>() {};
        for (int i = 0; i < orders.Count; i++)
        {
            object order = orders[i];
            string? status = this.parseOrderStatus(this.safeString2(order, "status", "order_status"));
            if (status != "open")
            {
                continue;
            }
            string? marketId = this.safeString(order, "conid");
            Dictionary<string, object> market = this.safeMarket(marketId);
            if ((this.safeBool(market, "contract", false) == true))
            {
                continue;
            }
            string? remaining = this.safeString2(order, "remainingQuantity", "size");
            if (((remaining == null)) || !Precise.stringGt(remaining, "0"))
            {
                continue;
            }
            string? side = this.safeStringUpper(order, "side");
            string? code = null;
            string? amount = null;
            if ((side == "BUY") || (side == "B"))
            {
                string? price = ((string)this.omitZero(this.safeString2(order, "price", "limit_price")));
                if ((price == null))
                {
                    continue;
                }
                string? cashCurrencyId = this.safeString(order, "cashCcy");
                if ((cashCurrencyId != null))
                {
                    code = this.safeCurrencyCode(cashCurrencyId);
                } else
                {
                    code = this.safeString(market, "quote");
                }
                amount = Precise.stringMul(remaining, price);
            } else if ((side == "SELL") || (side == "S"))
            {
                code = this.safeString(market, "base");
                amount = remaining;
            }
            if (((code == null)) || !((result != null && code != null && result.ContainsKey(code))))
            {
                continue;
            }
            string? previous = this.safeString(used, code, "0");
            used[(string)code] = Precise.stringAdd(previous, amount);
        }
        List<object> usedCodes = new List<object>(used.Keys);
        for (int i = 0; i < usedCodes.Count; i++)
        {
            string? code = ((string)usedCodes[i]);
            Dictionary<string, object> usedAccount = this.extend(new Dictionary<string, object>() {}, this.safeDict(result, code, new Dictionary<string, object>() {}));
            usedAccount["used"] = (code != null && used.ContainsKey(code) ? used[code] : null);
            result[(string)code] = usedAccount;
        }
        // every currency of the ledger and the positions gets a 'used' when the open orders were fetched, so that 'free' is computed
        if ((response != null && response.ContainsKey("orders")))
        {
            List<object> codes = new List<object>(result.Keys);
            for (int i = 0; i < codes.Count; i++)
            {
                string? code = ((string)codes[i]);
                if (((code != "info")) && ((this.safeString((code != null && result.ContainsKey(code) ? result[code] : null), "used") == null)))
                {
                    Dictionary<string, object> zeroAccount = this.extend(new Dictionary<string, object>() {}, this.safeDict(result, code, new Dictionary<string, object>() {}));
                    zeroAccount["used"] = "0";
                    result[(string)code] = zeroAccount;
                }
            }
        }
        Int64? timestamp = this.safeTimestamp(this.safeDict(ledger, "BASE", new Dictionary<string, object>() {}), "timestamp");
        result["timestamp"] = timestamp;
        result["datetime"] = this.iso8601(timestamp);
        return this.safeBalance(result);
    }

    /**
     * @method
     * @name interactivebrokers#ibkrBalanceCode
     * @description resolves the currency code of a position held as a balance, BTC for the BTC crypto, AAPL for the AAPL shares
     * @ignore
     * @param {object} position a raw position from portfolio2/{accountId}/positions
     * @returns {string|undefined} the currency code
     */
    public virtual string? ibkrBalanceCode(object position)
    {
        string? marketId = this.safeString(position, "conid");
        Dictionary<string, object> market = this.safeMarket(marketId);
        string? bs = this.safeString(market, "base");
        if ((bs != null))
        {
            return bs;
        }
        string? description = this.safeString2(position, "ticker", "description");
        if ((description == null))
        {
            return null;
        }
        string? assetClass = this.safeString2(position, "secType", "assetClass");
        List<object> parts = description.Split(new [] {" "}, StringSplitOptions.None).ToList<object>();
        if (assetClass == "CRYPTO")
        {
            // "ETH CRYPTO" -> ETH
            return this.safeCurrencyCode((parts != null && 0 < parts.Count ? parts[0] : null));
        }
        return String.Join(".", parts.ToArray());  // 'BRK B' -> 'BRK.B', as in parseMarket
    }

    /**
     * @method
     * @name interactivebrokers#beforeClose
     * @description stops the client portal gateway keep-alive and session-regain loops when close () is called, otherwise the scheduled tickles keep the event loop alive after close ()
     * @ignore
     * @returns {undefined}
     */
    public override object beforeClose()
    {
        this.options["gatewayKeepAlive"] = false;
        this.options["autoRegainSession"] = 0;
        return null;
    }

    public async override Task<IDictionary<string, object>> loadMarkets(bool? reload = null, IDictionary<string, object> parameters = null)
    {
        reload ??= false;
        parameters ??= new Dictionary<string, object>();
        await this.authenticate();
        return ((IDictionary<string, object>)((object)(await base.loadMarkets(reload, parameters))));
    }

    /**
     * @method
     * @name interactivebrokers#fetchMarkets
     * @description retrieves data on the market types of options.fetchMarkets.types: stocks of options.fetchMarkets.exchanges.STK, crypto of options.fetchMarkets.cryptoSpotSymbols, fx pairs of options.fetchMarkets.forexCurrencies, coinbase derivatives perp-style futures discovered with the market scanner (as swap, e.g. BTC/USD:USD), dated coinbase derivatives futures (scanned) and CME and CFE crypto futures of options.fetchMarkets.cryptoCmeFutureSymbols (as future, e.g. BTC/USD:USD-261127) and cfds of options.fetchMarkets.cfdExchanges (as swap, e.g. AAPL/USD:USD), bonds of options.fetchMarkets.bondSymbols are loaded only with 'bond' in options.fetchMarkets.types (as spot, e.g. US-T-4.125-270131.SMART/USD), the market id is the IBKR conid
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-conids-by-exchange
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-bond-filters
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-info-and-rules
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-future-by-symbol
     * @see https://www.interactivebrokers.com/campus/ibkr-api-page/cpapi-v1/#scanner-run
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-contract-symbols-from-body
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-currency-pairs
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-instrument-definition
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public async override Task<List<ccxt.MarketInterface>> FetchMarkets(IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        IDictionary<string, object> options = this.safeDict(this.options, "fetchMarkets", new Dictionary<string, object>() {});
        List<object> types = this.safeList(options, "types", new List<object>() {});
        List<object> promises = new List<object>() {};
        // the order matters, on symbol collisions the earlier contract keeps the plain symbol
        if (this.inArray("stock", types))
        {
            promises.Add(this.fetchStockMarkets(parameters));
        }
        if (this.inArray("crypto", types))
        {
            promises.Add(this.fetchCryptoMarkets(parameters));
        }
        if (this.inArray("forex", types))
        {
            promises.Add(this.fetchForexMarkets(parameters));
        }
        if (this.inArray("swap", types) || this.inArray("future", types))
        {
            // the swaps and the futures come from the same scans and requests
            promises.Add(this.fetchFuturesAndSwapMarkets(parameters));
        }
        if (this.inArray("cfd", types))
        {
            promises.Add(this.fetchCfdMarkets(parameters));
        }
        if (this.inArray("bond", types))
        {
            promises.Add(this.fetchBondMarkets(parameters));
        }
        List<object> results = await promiseAll(promises);
        List<object> markets = this.arraysConcat(results);
        return ccxt.BaseExchange.ToMarketInterfaceList(this.ibkrDisambiguateContractSymbols(markets));
    }

    /**
     * @method
     * @name interactivebrokers#ibkrDisambiguateContractSymbols
     * @description gives a unique symbol to the contract markets that share a symbol with an earlier market, e.g. the GRAYSCALE BITCOIN MINI ETF CFD (ticker BTC) and the BTC perp-style future both map to BTC/USD:USD, the cfd becomes BTC.IBUSCFD/USD:USD
     * @ignore
     * @param {object[]} markets parsed markets
     * @returns {object[]} the markets with unique symbols
     */
    public virtual List<object> ibkrDisambiguateContractSymbols(IList<object> markets)
    {
        Dictionary<string, object> seen = new Dictionary<string, object>() {};
        List<object> result = new List<object>() {};
        for (int i = 0; i < (markets?.Count ?? 0); i++)
        {
            Dictionary<string, object> market = this.extend(new Dictionary<string, object>() {}, markets[i]);
            string symbol = this.safeString(market, "symbol");
            bool? isContract = this.safeBool(market, "contract", false);
            if ((((symbol != null) && (seen?.ContainsKey(symbol) == true))) && (isContract == true))
            {
                IDictionary<string, object> info = this.safeDict(market, "info", new Dictionary<string, object>() {});
                string? listingExchange = this.safeString2(info, "listingExchange", "exchange", "default");
                string marketBase = this.safeString(market, "base", "");
                string? marketBaseId = this.safeString(market, "baseId", "");
                bool? isFuture = this.safeBool(market, "future", false);
                // keeps the quote, settle and the expiry suffix of futures, e.g. /USD:USD-261127
                List<object> symbolParts = symbol.Split(new [] {"/"}, StringSplitOptions.None).ToList<object>();
                string? quotePart = this.safeString(symbolParts, 1, "");
                string quoteAndSettle = ("/" + quotePart);
                string bs = ((marketBase + ".") + listingExchange);
                if ((isFuture == true) && ((marketBaseId != marketBase)))
                {
                    // the futures of the same base and expiry (BRR, MBT, BFF) are told apart by the IBKR ticker, e.g. BTC.MBT/USD:USD-261127
                    bs = ((marketBase + ".") + marketBaseId);
                }
                string newSymbol = (bs + quoteAndSettle);
                if (((newSymbol != null) && (seen?.ContainsKey(newSymbol) == true)))
                {
                    string? marketId = this.safeString(market, "id", "");
                    bs = ((marketBase + ".") + marketId);
                    newSymbol = (bs + quoteAndSettle);
                }
                market = this.extend(market, new Dictionary<string, object>() {
                    { "symbol", newSymbol },
                    { "base", bs },
                });
            }
            string finalSymbol = this.safeString(market, "symbol");
            seen[(string)finalSymbol] = true;
            result.Add(market);
        }
        return result;
    }

    public async virtual Task<List<object>> fetchSecWithDetails(IDictionary<string, object> plainEntries)
    {
        List<object> detailIds = new List<object>(plainEntries.Keys);
        List<object> entries = new List<object>() {};
        int numDetails = detailIds.Count;
        if ((numDetails == 0))
        {
            return entries;
        }
        int chunkSize = 330; // above this number, response becomes unreliable
        List<object> promises = new List<object>() {};
        List<object> chunk = new List<object>() {};
        for (int k = 0; k < numDetails; k++)
        {
            string? detailId = this.safeString(detailIds, k, "");
            chunk.Add(detailId);
            int chunkLength = (chunk?.Count ?? 0);
            if (((chunkLength == chunkSize)) || ((k == (numDetails - 1))))
            {
                Dictionary<string, object> secdefRequest = new Dictionary<string, object>() {
                    { "conids", String.Join(",", chunk.ToArray()) },
                };
                promises.Add(this.marketsEndpointCall(secdefRequest, "webapiGetV1ApiTrsrvSecdef", new Dictionary<string, object>() {}));
                chunk = new List<object>() {};
            }
        }
        List<object> responses = await promiseAll(promises);
        //
        //     {
        //         "secdef": [
        //             {
        //                 "conid": 479624278,
        //                 "currency": "USD",
        //                 "incrementRules": [ { "lowerEdge": 0, "increment": 0.25 } ],
        //                 "listingExchange": "PAXOS",
        //                 "assetClass": "CRYPTO",
        //                 "ticker": "BTC",
        //                 ...
        //             }
        //         ]
        //     }
        //
        for (int i = 0; i < (responses?.Count ?? 0); i++)
        {
            List<object> secdefs = this.safeList(responses[i], "secdef", new List<object>() {});
            for (int j = 0; j < secdefs.Count; j++)
            {
                object secdef = secdefs[j];
                string? conid = this.safeString(secdef, "conid", "");
                IDictionary<string, object> entry = this.safeDict(plainEntries, conid);
                entries.Add(this.extend(entry, secdef));
            }
        }
        return entries;
    }

    public async virtual Task<object> fetchForexMarkets(IDictionary<string, object>? parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> entries = new Dictionary<string, object>() {};
        IDictionary<string, object> options = this.safeDict(this.options, "fetchMarkets", new Dictionary<string, object>() {});
        List<object> forexCurrencies = this.safeList(options, "forexCurrencies", new List<object>() {});
        List<object> promises = new List<object>() {};
        for (int i = 0; i < forexCurrencies.Count; i++)
        {
            object fxCurrency = forexCurrencies[i];
            Dictionary<string, object> pairsRequest = new Dictionary<string, object>() {
                { "currency", fxCurrency },
            };
            promises.Add(this.marketsEndpointCall(this.extend(pairsRequest, parameters), "webapiGetV1ApiIserverCurrencyPairs", new Dictionary<string, object>() {}));
        }
        List<object> fxResults = await promiseAll(promises);
        for (int i = 0; i < (fxResults?.Count ?? 0); i++)
        {
            object pairsResponse = fxResults[i];
            object fxCurrency = (forexCurrencies != null && i < forexCurrencies.Count ? forexCurrencies[i] : null);
            List<object> pairs = this.safeList(pairsResponse, fxCurrency, new List<object>() {});
            for (int j = 0; j < pairs.Count; j++)
            {
                object pair = pairs[j];
                string? conid = this.safeString(pair, "conid");
                if ((conid != null))
                {
                    entries[(string)conid] = pair;
                }
            }
        }
        List<object> detailMarkets = await this.fetchSecWithDetails(entries);
        return this.parseMarkets(detailMarkets);
    }

    public async virtual Task<object> fetchCryptoMarkets(IDictionary<string, object>? parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> entries = new Dictionary<string, object>() {};
        IDictionary<string, object> options = this.safeDict(this.options, "fetchMarkets", new Dictionary<string, object>() {});
        List<object> cryptoSpotSymbols = this.safeList(options, "cryptoSpotSymbols", new List<object>() {});
        List<object> promises = new List<object>() {};
        for (int i = 0; i < cryptoSpotSymbols.Count; i++)
        {
            object cryptoSymbol = cryptoSpotSymbols[i];
            Dictionary<string, object> searchRequest = new Dictionary<string, object>() {
                { "symbol", cryptoSymbol },
                { "secType", "CRYPTO" },
            };
            promises.Add(this.marketsEndpointCall(this.extend(searchRequest, parameters), "webapiPostV1ApiIserverSecdefSearch", new List<object>() {}));
        }
        List<object> results = await promiseAll(promises);
        List<object> neededSecTypes = new List<object>() {"CRYPTO"}; // CFD, OPT - they should already be fetched in other calls
        for (int i = 0; i < (results?.Count ?? 0); i++)
        {
            List<object> result = this.safeList(results, i, new List<object>() {});
            for (int j = 0; j < result.Count; j++)
            {
                object entry = result[j];
                List<object> sections = this.safeList(entry, "sections", new List<object>() {});
                for (int k = 0; k < sections.Count; k++)
                {
                    string? secType = this.safeString(sections[k], "secType");
                    if (this.inArray(secType, neededSecTypes))
                    {
                        string? conid = this.safeString(entry, "conid");
                        if ((conid != null))
                        {
                            entries[(string)conid] = entry;
                        }
                    }
                }
            }
        }
        List<object> detailMarkets = await this.fetchSecWithDetails(entries);
        return this.parseMarkets(detailMarkets);
    }

    /**
     * @method
     * @name interactivebrokers#fetchCoinbaseDerivativesSymbols
     * @description discovers the coinbase derivatives (COINDERIV) futures symbols with the market scanner, the MOST_ACTIVE scan misses the contracts that have not traded yet, so it is merged with the NOT_YET_TRADED_TODAY scan
     * @ignore
     * @see https://www.interactivebrokers.com/campus/ibkr-api-page/cpapi-v1/#scanner-run
     * @returns {string[]} the unique IBKR symbols, e.g. [ 'BIP', 'ETP', 'BIT', ... ]
     */
    public async virtual Task<List<object>> fetchCoinbaseDerivativesSymbols()
    {
        List<object> scanTypes = new List<object>() {"MOST_ACTIVE", "NOT_YET_TRADED_TODAY"}; // these two ones cover all coinbase symbols
        List<object> result = new List<object>() {};
        // the scans are run one by one, the scanner rejects concurrent requests
        for (int i = 0; i < (scanTypes?.Count ?? 0); i++)
        {
            if ((i != 0))
            {
                await this.sleep(1000); // wait for 1 second before running the next scan
            }
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "instrument", "FUT.US" },
                { "location", "FUT.COINDERIV" },
                { "type", scanTypes[i] },
                { "filter", new List<object>() {} },
            };
            object response = await this.marketsEndpointCall(request, "webapiPostV1ApiIserverScannerRun", new Dictionary<string, object>() {});
            //
            //     {
            //         "contracts": [
            //             {
            //                 "server_id": "0",
            //                 "column_name": "Volume",
            //                 "symbol": "BIP",
            //                 "conidex": "805366677@COINDERIV",
            //                 "con_id": 805366677,
            //                 "company_name": "nano Bitcoin BTC Perpetual Futures",
            //                 "contract_description_1": "Dec'30",
            //                 "listing_exchange": "COINDERIV",
            //                 "sec_type": "FUT"
            //             }
            //         ],
            //         "scan_data_column_name": "Volume"
            //     }
            //
            List<object> contracts = this.safeList(response, "contracts", new List<object>() {});
            for (int j = 0; j < contracts.Count; j++)
            {
                object contract = contracts[j];
                string? listingExchange = this.safeString(contract, "listing_exchange");
                string? symbol = this.safeString(contract, "symbol");
                if (((symbol != null)) && (listingExchange == "COINDERIV") && !this.inArray(symbol, result))
                {
                    result.Add(symbol);
                }
            }
        }
        return result;
    }

    /**
     * @method
     * @name interactivebrokers#fetchFuturesAndSwapMarkets
     * @description retrieves the coinbase derivatives (COINDERIV) perp-style futures (as swaps) and dated futures, whose symbols are discovered with the market scanner, together with the CME and CFE dated crypto futures of options.fetchMarkets.cryptoCmeFutureSymbols, the swaps are kept with 'swap' in options.fetchMarkets.types and the futures with 'future'
     * @ignore
     * @see https://www.interactivebrokers.com/campus/ibkr-api-page/cpapi-v1/#scanner-run
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-future-by-symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public async virtual Task<List<object>> fetchFuturesAndSwapMarkets(IDictionary<string, object>? parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        IDictionary<string, object> options = this.safeDict(this.options, "fetchMarkets", new Dictionary<string, object>() {});
        List<object> types = this.safeList(options, "types", new List<object>() {});
        IDictionary<string, object> cryptoCmeFutureSymbols = this.safeDict(options, "cryptoCmeFutureSymbols", new Dictionary<string, object>() {});
        IDictionary<string, object> cryptoCboeFutureSymbols = this.safeDict(options, "cryptoCboeFutureSymbols", new Dictionary<string, object>() {});
        List<object> coinbaseDerivSymbols = await this.fetchCoinbaseDerivativesSymbols();
        List<object> cmeSymbols = new List<object>(cryptoCmeFutureSymbols.Keys);
        List<object> cfeSymbols = new List<object>(cryptoCboeFutureSymbols.Keys);
        List<object> targetSymbols = this.arraysConcat(new List<object>() {coinbaseDerivSymbols, cmeSymbols, cfeSymbols});
        List<object> symbols = this.unique(targetSymbols);
        string joined = String.Join(",", symbols.ToArray()); // c# fix, todo investigate
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "symbols", joined },
        };
        object response = await this.marketsEndpointCall(this.extend(request, parameters), "webapiGetV1ApiTrsrvFutures", new Dictionary<string, object>() {});
        //
        //     {
        //         "MBT": [
        //             {
        //                 "symbol": "MBT",
        //                 "conid": 750093370,
        //                 "underlyingConid": 479624278,
        //                 "expirationDate": 20261127,
        //                 "ltd": 20261127,
        //                 "shortFuturesCutOff": 20261127,
        //                 "longFuturesCutOff": 20261127
        //             }
        //         ]
        //     }
        //
        // (for swaps, the date is "20301220")
        //
        Dictionary<string, object> entries = new Dictionary<string, object>() {};
        for (int i = 0; i < (symbols?.Count ?? 0); i++)
        {
            List<object> contracts = this.safeList(response, symbols[i], new List<object>() {});
            for (int j = 0; j < contracts.Count; j++)
            {
                object contract = contracts[j];
                string? conid = this.safeString(contract, "conid");
                if ((conid != null))
                {
                    entries[(string)conid] = contract;
                }
            }
        }
        List<object> details = await this.fetchSecWithDetails(entries);
        // generic tickers (e.g. SOL, XRP, ADA, XLM) are queried by bare symbol, so trsrv/futures can return
        // unrelated contracts listed on other venues (e.g. EUREX), only the crypto futures venues are kept
        List<object> allowedVenues = new List<object>() {"CME", "CFE", "COINDERIV"};
        List<object> detailMarkets = new List<object>() {};
        for (int i = 0; i < (details?.Count ?? 0); i++)
        {
            string? venue = this.safeString((details != null && i < details.Count ? details[i] : null), "listingExchange");
            if (this.inArray(venue, allowedVenues))
            {
                detailMarkets.Add(this.safeDict(details, i));
            }
        }
        IList<object> markets = this.parseMarkets(detailMarkets);
        bool withSwaps = this.inArray("swap", types);
        bool withFutures = this.inArray("future", types);
        List<object> result = new List<object>() {};
        for (int i = 0; i < (markets?.Count ?? 0); i++)
        {
            object market = markets[i];
            string? parsedType = this.safeString(market, "type");
            if (withSwaps && (parsedType == "swap"))
            {
                result.Add(market);
            } else if (withFutures && (parsedType == "future"))
            {
                result.Add(market);
            }
        }
        return result;
    }

    /**
     * @method
     * @name interactivebrokers#fetchCfdMarkets
     * @description retrieves the cfd contracts listed on options.fetchMarkets.cfdExchanges
     * @ignore
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-conids-by-exchange
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public async virtual Task<object> fetchCfdMarkets(IDictionary<string, object>? parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> entries = new Dictionary<string, object>() {};
        IDictionary<string, object> options = this.safeDict(this.options, "fetchMarkets", new Dictionary<string, object>() {});
        List<object> cfdExchanges = this.safeList(options, "cfdExchanges", new List<object>() {});
        List<object> promises = new List<object>() {};
        for (int i = 0; i < cfdExchanges.Count; i++)
        {
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "exchange", this.safeString(cfdExchanges, i, "") },
                { "assetClass", "CFD" },
            };
            promises.Add(this.marketsEndpointCall(request, "webapiGetV1ApiTrsrvAllConids", new List<object>() {}));
        }
        List<object> responses = await promiseAll(promises);
        for (int i = 0; i < (responses?.Count ?? 0); i++)
        {
            List<object> cfds = this.safeList(responses, i, new List<object>() {});
            for (int j = 0; j < cfds.Count; j++)
            {
                object cfd = cfds[j];
                string conid = this.safeString(cfd, "conid");
                entries[(string)conid] = cfd;
            }
        }
        List<object> detailMarkets = await this.fetchSecWithDetails(entries);
        // keep the order of options.fetchMarkets.cfdExchanges, the first exchange wins the plain symbol on collisions
        List<object> result = new List<object>() {};
        int detailMarketsLength = (detailMarkets?.Count ?? 0);
        for (int i = 0; i < cfdExchanges.Count; i++)
        {
            string? cfdExchange = this.safeString(cfdExchanges, i, "");
            for (int j = 0; j < detailMarketsLength; j++)
            {
                string? listingExchange = this.safeString((detailMarkets != null && j < detailMarkets.Count ? detailMarkets[j] : null), "listingExchange", "");
                if ((listingExchange == cfdExchange))
                {
                    result.Add(this.safeDict(detailMarkets, j));
                }
            }
        }
        return this.parseMarkets(result);
    }

    /**
     * @method
     * @name interactivebrokers#fetchBondMarkets
     * @description retrieves the bonds of the issuers of options.fetchMarkets.bondSymbols, narrowed by options.fetchMarkets.bondFilters
     * @ignore
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-contract-symbols-from-body
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-bond-filters
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-contracts/get-info-and-rules
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public async virtual Task<List<object>> fetchBondMarkets(IDictionary<string, object>? parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> entries = new Dictionary<string, object>() {};
        IDictionary<string, object> options = this.safeDict(this.options, "fetchMarkets", new Dictionary<string, object>() {});
        List<object> bondSymbols = this.safeList(options, "bondSymbols", new List<object>() {});
        IDictionary<string, object> bondFilters = this.safeDict(options, "bondFilters", new Dictionary<string, object>() {});
        List<object> searchPromises = new List<object>() {};
        for (int i = 0; i < bondSymbols.Count; i++)
        {
            Dictionary<string, object> searchRequest = new Dictionary<string, object>() {
                { "symbol", this.safeString(bondSymbols, i, "") },
                { "secType", "BOND" },
            };
            searchPromises.Add(this.marketsEndpointCall(this.extend(searchRequest, parameters), "webapiPostV1ApiIserverSecdefSearch", new List<object>() {}));
        }
        List<object> searchResults = await promiseAll(searchPromises);
        // the filters are sent as columnId:value pairs joined by a comma, e.g. 29:Notes,27:202701
        List<object> filterIds = new List<object>(bondFilters.Keys);
        List<object> filterParts = new List<object>() {};
        for (int i = 0; i < filterIds.Count; i++)
        {
            string filterId = ((string)filterIds[i]);
            string? filterValue = this.safeString(bondFilters, filterId, "");
            filterParts.Add(((filterId + ":") + filterValue));
        }
        int filterPartsLength = (filterParts?.Count ?? 0);
        List<object> contractPromises = new List<object>() {};
        for (int i = 0; i < (searchResults?.Count ?? 0); i++)
        {
            List<object> searchResult = this.safeList(searchResults, i, new List<object>() {});
            for (int j = 0; j < searchResult.Count; j++)
            {
                List<object> issuers = this.safeList(searchResult[j], "issuers", new List<object>() {});
                for (int k = 0; k < issuers.Count; k++)
                {
                    Dictionary<string, object> contractsRequest = new Dictionary<string, object>() {
                        { "sectype", "BOND" },
                        { "issuerId", this.safeString(issuers[k], "id") },
                    };
                    if (filterPartsLength > 0)
                    {
                        contractsRequest["filters"] = String.Join(",", filterParts.ToArray());
                    }
                    contractPromises.Add(this.marketsEndpointCall(contractsRequest, "webapiGetV1ApiIserverSecdefInfo", new List<object>() {}));
                }
            }
        }
        List<object> contractResults = await promiseAll(contractPromises);
        //
        //  [
        //    {
        //        "conid": 15960430,
        //        "symbol": "US-T",
        //        "secType": "BOND",
        //        "exchange": "SMART",
        //        "listingExchange": "BONDDESKG",
        //        "right": "?",
        //        "strike": "0",
        //        "currency": "USD",
        //        "cusip": "912810EY0",
        //        "coupon": "6.5",
        //        "desc1": "US-T",
        //        "desc2": "GOVT 6.5 Nov15'26 912810EY0 WR",
        //        "maturityDate": "20261115",
        //        "multiplier": 0,
        //        "tradingClass": "US-T",
        //        "validExchanges": "SMART",
        //        "incrementRules": [
        //            {
        //                "lowerEdge": 0,
        //                "increment": 0.001
        //            }
        //        ],
        //        "displayRule": {
        //            "magnification": 0,
        //            "displayRuleStep": [
        //                {
        //                    "decimalDigits": 3,
        //                    "lowerEdge": 0,
        //                    "wholeDigits": 4
        //                }
        //            ]
        //        },
        //        "time": 11,
        //        "chineseName": "&#x7F8E;&#x56FD;&#x4E2D;&#x957F;&#x671F;&#x56FD;&#x503A;",
        //        "allExchanges": "BONDDESKG,VALUBONDG,CITADEL,VIRTBONDG,TRADEWEBG,TRACE,BONDSCOM,JPMCUSG",
        //        "countryCode": "US",
        //        "name": "US-T",
        //        "assetClass": "BOND",
        //        "expiry": null,
        //        "lastTradingDay": null,
        //        "group": null,
        //        "putOrCall": null,
        //        "sector": null,
        //        "sectorGroup": null,
        //        "ticker": "US-T",
        //        "undConid": 0,
        //        "type": "Govt",
