        IDictionary<string, object> options = this.safeDict(this.options, "fetchMarkets", new Dictionary<string, object>() {});
        string baseTickerId = this.safeString2(market, "ticker", "symbol");
        string? listingExchange = this.safeString2(market, "listingExchange", "exchange", "default");
        if (isBond)
        {
            // bonds trade across many venues (BONDDESKG, TRADEWEBG, ...) and are routed by SMART, the listing exchange is an arbitrary one of them
            listingExchange = this.safeString(market, "exchange", "SMART");
        }
        string? name = this.safeString(market, "name", "");
        string nameLower = name.ToLower();
        // coinbase derivatives perp-style futures are listed as FUT with a far (2030) nominal expiry, they are rolled with a funding adjustment, so they are unified as swaps
        // cfds are undated, cash-settled linear contracts on a stock, etf or index, also unified as swaps
        // the other FUT contracts (CME and coinbase derivatives dated crypto futures) are unified as futures
        bool isCfd = (assetClass == "CFD");
        bool isFut = (assetClass == "FUT");
        string? expirationDate = this.safeString2(market, "expirationDate", "expiry"); // 20261127
        bool isCoinbaseDerivatives = (listingExchange == "COINDERIV");
        bool isCme = (listingExchange == "CME");
        bool isCfe = (listingExchange == "CFE");
        // checking for 'Perpetual' or 'Perp Style' in the name is weaker
        bool isCoinbasePerp = isCoinbaseDerivatives && (expirationDate == "20301220"); // five year PERP cycle end
        bool isPerpetual = isCoinbasePerp; // no other perp providers
        bool isPerp = (isFut && isPerpetual) || isCfd;
        bool isFuture = isFut && !isPerpetual;
        bool isContract = isFuture || isPerp;
        bool isSpot = !isContract;
        string? id = this.safeString(market, "conid");
        string? quoteId = this.safeString(market, "currency");
        string? quote = this.safeCurrencyCode(quoteId);
        List<object> incrementRules = this.safeList(market, "incrementRules", new List<object>() {});
        IDictionary<string, object> firstRule = this.safeDict(incrementRules, 0, new Dictionary<string, object>() {});
        string? incrementTickSize = this.safeString(firstRule, "increment");
        string? amountPrecision = null;
        if (isCrypto)
        {
            amountPrecision = this.safeString(options, "cryptoAmountIncrement", "0.00000001");
        } else if (isForex)
        {
            amountPrecision = this.safeString(options, "forexAmountIncrement", "1");
        } else if (isBond)
        {
            amountPrecision = this.safeString(options, "bondAmountIncrement", "1");
        } else if (isContract)
        {
            amountPrecision = this.safeString(options, "contractAmountIncrement", "1");
        } else
        {
            amountPrecision = this.safeString(options, "stockAmountIncrement", "1");
        }
        IDictionary<string, object> cryptoCoinbasePerpSymbols = this.safeDict(options, "cryptoCoinbasePerpSymbols", new Dictionary<string, object>() {});
        IDictionary<string, object> cryptoCmeFutureSymbols = this.safeDict(options, "cryptoCmeFutureSymbols", new Dictionary<string, object>() {});
        IDictionary<string, object> cryptoCboeFutureSymbols = this.safeDict(options, "cryptoCboeFutureSymbols", new Dictionary<string, object>() {});
        string microNanoPrefix = "";
        object bs = this.safeCurrencyCode(baseTickerId);
        string? contractSize = null;
        Int64? expiry = null;
        if (isFut)
        {
            if (isCoinbaseDerivatives)
            {
                bs = this.safeString(cryptoCoinbasePerpSymbols, baseTickerId, baseTickerId);
            } else if (isCme)
            {
                bs = this.safeString(cryptoCmeFutureSymbols, baseTickerId, baseTickerId);
            } else if (isCfe)
            {
                bs = this.safeString(cryptoCboeFutureSymbols, baseTickerId, baseTickerId);
            }
        }
        if (isPerp && !isCfd)
        {
            if (nameLower.StartsWith("nano "))
            {
                microNanoPrefix = "NANO.";
            }
            contractSize = this.safeString(market, "multiplier"); // 0.01 BTC for BIP
        } else if (isFuture)
        {
            if (nameLower.StartsWith("nano "))
            {
                microNanoPrefix = "NANO.";
            } else if (nameLower.StartsWith("micro "))
            {
                microNanoPrefix = "MICRO.";
            } else if (((name?.IndexOf("New York Variant", StringComparison.Ordinal) ?? -1) != -1))
            {
                microNanoPrefix = "NEWYORK.";
            }
            contractSize = this.safeString(market, "multiplier"); // 0.1 BTC for MBT, 5 BTC for BRR
            if ((expirationDate != null))
            {
                string expiryDatetime = (((((((expirationDate == null) ? null : expirationDate.Substring(0, Math.Min(4, expirationDate.Length))) + "-") + ((expirationDate == null) ? null : expirationDate.Substring(Math.Min(4, expirationDate.Length), Math.Min(6, expirationDate.Length) - Math.Min(4, expirationDate.Length)))) + "-") + ((expirationDate == null) ? null : expirationDate.Substring(Math.Min(6, expirationDate.Length), Math.Min(8, expirationDate.Length) - Math.Min(6, expirationDate.Length)))) + "T00:00:00Z");
                expiry = this.parse8601(expiryDatetime);
            }
        } else if (isBond)
        {
            // every bond of an issuer has the same ticker, the coupon and the maturity tell them apart, US-T-4.125-270131 (US-T-270114 without a coupon)
            bs = baseTickerId;
            string? coupon = this.safeString(market, "coupon", ""); // "No Coupon" for bills and strips
            if ((coupon != "") && (((coupon?.IndexOf(" ", StringComparison.Ordinal) ?? -1) == -1)))
            {
                bs = ((object)(bs == null ? null : bs + "-" + coupon));
            }
            string? maturityDate = this.safeString(market, "maturityDate"); // 20270131
            if ((maturityDate != null))
            {
                bs = ((object)(bs == null ? null : bs + "-" + ((maturityDate == null) ? null : maturityDate.Substring(Math.Min(2, maturityDate.Length), Math.Min(8, maturityDate.Length) - Math.Min(2, maturityDate.Length)))));
            }
        } else if (isStock || isCfd)
        {
            // stock and cfd tickers are not currencies, skip commonCurrencies remapping, 'BRK B' -> 'BRK.B'
            List<object> tickerParts = baseTickerId.Split(new [] {" "}, StringSplitOptions.None).ToList<object>();
            bs = String.Join(".", tickerParts.ToArray());
            if (isCfd)
            {
                contractSize = "1"; // one cfd is one share or index point, the multiplier is reported as 0 or 1
            }
        } else
        {
            if (!isSpot)
            {
                contractSize = this.safeString(this.options, "defaultContractSize", "1");
            }
        }
        object symbol = ((object)(bs == null ? null : bs + "." + microNanoPrefix + listingExchange + "/" + quote)); // specific to IBKR
        string? settleId = null;
        string? settle = null;
        if (isContract)
        {
            settleId = quoteId;
            settle = quote;
            symbol = ((object)(bs == null ? null : bs + "." + microNanoPrefix + listingExchange + "/" + quote + ":" + settle));
            if (isFuture)
            {
                symbol = ((object)(bs == null ? null : bs + "." + microNanoPrefix + listingExchange + "/" + quote + ":" + settle + "-" + (string)(object)(this.yymmdd(expiry))));
            }
        }
        string marketType = "spot";
        if (isPerp)
        {
            marketType = "swap";
        } else if (isFuture)
        {
            marketType = "future";
        }
        return this.safeMarketStructure(new Dictionary<string, object>() {
            { "id", id },
            { "symbol", symbol },
            { "quote", quote },
            { "quoteId", quoteId },
            { "base", bs },
            { "baseId", baseTickerId },
            { "settle", settle },
            { "settleId", settleId },
            { "type", marketType },
            { "spot", isSpot },
            { "margin", false },
            { "swap", isPerp },
            { "future", isFuture },
            { "option", false },
            { "active", true },
            { "contract", isContract },
            { "linear", isContract ? true : null },
            { "inverse", isContract ? false : null },
            { "contractSize", this.parseNumber(contractSize) },
            { "expiry", expiry },
            { "expiryDatetime", this.iso8601(expiry) },
            { "strike", null },
            { "optionType", null },
            { "precision", new Dictionary<string, object>() {
                { "amount", this.parseNumber(amountPrecision) },
                { "price", this.parseNumber(incrementTickSize) },
            } },
            { "limits", new Dictionary<string, object>() {
                { "leverage", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "amount", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "price", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "cost", new Dictionary<string, object>() {
                    { "min", this.safeNumber(options, "defaultMinCost", 1) },
                    { "max", null },
                } },
            } },
            { "created", null },
            { "info", market },
        });
    }

    /**
     * @method
     * @name interactivebrokers#fetchTickers
     * @description fetches price tickers for multiple markets, the first snapshot request only subscribes to the market data, so the request is retried until data arrives
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-market-data/get-md-snapshot
     * @param {string[]} symbols unified symbols of the markets to fetch the ticker for
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.fields] comma-separated snapshot field ids, max 50
     * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
     */
    public async override Task<ccxt.Tickers> FetchTickers(IList<object> symbols = null, IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((symbols == null))
        {
            throw new ArgumentsRequired ((this.id + " fetchTickers() requires a symbols argument")) ;
        }
        await this.authenticate();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        IList<object> symbolsNormalized = this.marketSymbols(symbols);
        var fieldsqueryVariable = this.handleOptionAndParams(parameters, "fetchTickers", "fields");
        var fields = ((IList<object>) fieldsqueryVariable)[0];
        var query = ((IList<object>) fieldsqueryVariable)[1];
        string fieldsString = String.Join(",", ((IList<object>)fields).ToArray());
        List<object> readyFields = new List<object>() {"31", "84", "86"};
        List<object> response = await this.ibkrFetchSnapshot(symbolsNormalized, fieldsString, readyFields, query);
        //
        //     [
        //         {
        //             "31": "82838.50",
        //             "70": "85639.25",
        //             "71": "82209.75",
        //             "84": "82836.00",
        //             "85": "0.00018171",
        //             "86": "82843.75",
        //             "88": "0.27167244",
        //             "6509": "R",
        //             "7762": "78",
        //             "conidEx": "479624278",
        //             "_updated": 1791449398940,
        //             "conid": 479624278
        //         }
        //     ]
        //
        return ccxt.BaseExchange.ToTickers(this.parseTickers(response, symbolsNormalized));
    }

    /**
     * @method
     * @name interactivebrokers#ibkrFetchSnapshot
     * @description fetches a market data snapshot, the first snapshot request only subscribes to the market data, so the request is retried until data arrives
     * @ignore
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-market-data/get-md-snapshot
     * @param {string[]} symbols unified market symbols
     * @param {string} fields comma-separated snapshot field ids
     * @param {string[]} readyFields the snapshot is ready once every item has at least one of these fields
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} the raw snapshot items
     */
    public async virtual Task<List<object>> ibkrFetchSnapshot(IList<object> symbols, object fields, IList<object> readyFields, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> conids = new List<object>() {};
        for (int i = 0; i < (symbols?.Count ?? 0); i++)
        {
            Dictionary<string, object> market = this.market(symbols[i]);
            conids.Add(this.safeString(market, "id", ""));
        }
        IDictionary<string, object> options = this.safeDict(this.options, "fetchTickers", new Dictionary<string, object>() {});
        Int64? retries = this.safeInteger(options, "retries", 5);
        Int64? retryDelay = this.safeInteger(options, "retryDelay", 500);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "conids", String.Join(",", conids.ToArray()) },
            { "fields", fields },
        };
        List<object> response = new List<object>() {};
        for (int i = 0; i <= retries.GetValueOrDefault(); i++)
        {
            response = await this.webapiGetV1ApiIserverMarketdataSnapshot(this.extend(request, parameters));
            if (this.ibkrSnapshotReady(response, readyFields))
            {
                break;
            }
            if (i < retries.GetValueOrDefault())
            {
                await this.sleep(retryDelay);
            }
        }
        return response;
    }

    public virtual bool ibkrSnapshotReady(IList<object> response, IList<object> fieldIds)
    {
        int numItems = response?.Count ?? 0;
        if ((numItems == 0))
        {
            return false;
        }
        int numFields = (fieldIds?.Count ?? 0);
        for (int i = 0; i < numItems; i++)
        {
            bool found = false;
            for (int j = 0; j < numFields; j++)
            {
                if ((this.safeString((response != null && i < response.Count ? response[i] : null), (fieldIds != null && j < fieldIds.Count ? fieldIds[j] : null)) != null))
                {
                    found = true;
                    break;
                }
            }
            if (!found)
            {
                return false;
            }
        }
        return true;
    }

