        Dictionary<string, object> response = await this.webapiPostV1ApiIserverAuthStatus(parameters);
        //
        //     {
        //         "authenticated": true,
        //         "competing": false,
        //         "connected": true,
        //         "message": "",
        //         "MAC": "12:B:B3:23:BF:A0",
