    }

    public virtual string? ibkrParseValue(object value)
    {
        // snapshot values are formatted strings: "C82838.50" (prior close), "H1.2" (halted), "+1.04", "1.5%", "1M", "1,234", "$11,000K" (bond sizes, the principal amount)
        if (((value == null)) || ((value is "")) || ((value is "N/A")))
        {
            return null;
        }
        List<object> valueParts = ((string)value).Split(new [] {","}, StringSplitOptions.None).ToList<object>();
        string? result = String.Join("", valueParts.ToArray());
        if (result.StartsWith("C") || result.StartsWith("H") || result.StartsWith("+") || result.StartsWith("$"))
        {
            result = ((result == null) ? null : result.Substring(Math.Min(1, result.Length)));
        }
        if (result.EndsWith("%"))
        {
            result = ((result == null) ? null : result.Substring(0, Math.Max(Math.Min(((result.Length - 1) < 0 ? result.Length + ((result.Length - 1)) : (result.Length - 1)), result.Length), 0)));
        }
        string? multiplier = null;
        if (result.EndsWith("K"))
        {
            multiplier = "1000";
        } else if (result.EndsWith("M"))
        {
            multiplier = "1000000";
        } else if (result.EndsWith("B"))
        {
            multiplier = "1000000000";
        }
        if ((multiplier != null))
        {
            return ((string?)((object)(Precise.stringMul(((result == null) ? null : result.Substring(0, Math.Max(Math.Min(((result.Length - 1) < 0 ? result.Length + ((result.Length - 1)) : (result.Length - 1)), result.Length), 0))), multiplier))));
        }
        if (result == "")
        {
            return null;
        }
        return result;
    }

    public override ccxt.Ticker parseTicker(IDictionary<string, object> ticker, IDictionary<string, object> market = null)
    {
        string? marketId = this.safeString(ticker, "conid");
        Dictionary<string, object> resolved = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeInteger(ticker, "_updated");
        string? last = this.ibkrParseValue(this.safeString(ticker, "7296")); // 31 might contain symbol
        if ((last == null))
        {
            // if precise fields are not provided, use generic "last price" field
            last = this.ibkrParseValue(this.safeString(ticker, "31"));
        }
        return this.safeTicker(new Dictionary<string, object>() {
            { "symbol", (resolved != null && resolved.ContainsKey("symbol") ? resolved["symbol"] : null) },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "high", this.ibkrParseValue(this.safeString(ticker, "70")) },
            { "low", this.ibkrParseValue(this.safeString(ticker, "71")) },
            { "bid", this.ibkrParseValue(this.safeString(ticker, "84")) },
            { "bidVolume", this.ibkrParseValue(this.safeString(ticker, "88")) },
            { "ask", this.ibkrParseValue(this.safeString(ticker, "86")) },
            { "askVolume", this.ibkrParseValue(this.safeString(ticker, "85")) },
            { "vwap", null },
            { "open", this.ibkrParseValue(this.safeString(ticker, "7295")) },
            { "close", last },
            { "last", last },
            { "previousClose", this.ibkrParseValue(this.safeString(ticker, "7741")) },
            { "change", this.ibkrParseValue(this.safeString(ticker, "82")) },
            { "percentage", this.ibkrParseValue(this.safeString(ticker, "83")) },
            { "average", null },
            { "baseVolume", this.ibkrParseValue(this.safeString(ticker, "7762")) },
            { "quoteVolume", null },
            { "markPrice", this.ibkrParseValue(this.safeString(ticker, "7635")) },
            { "indexPrice", null },
            { "info", ticker },
        }, resolved);
    }

    /**
     * @method
     * @name interactivebrokers#fetchOHLCV
     * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-market-data/get-md-history
     * @param {string} symbol unified symbol of the market to fetch OHLCV data for
     * @param {string} timeframe the length of time each candle represents
     * @param {int} [since] timestamp in ms of the earliest candle to fetch
     * @param {int} [limit] the maximum amount of candles to fetch, max 1000
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.outsideRth] include data outside regular trading hours
     * @param {string} [params.source] 'Last', 'Bid_Ask' or 'Midpoint'
     * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
     */
    public async override Task<List<ccxt.OHLCV>> FetchOHLCV(string symbol, string timeframe = null, Int64? since = null, Int64? limit = null, IDictionary<string, object> parameters = null)
    {
        string timeframeVar = timeframe;
        timeframeVar ??= "1m";
        parameters ??= new Dictionary<string, object>();
        await this.authenticate();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> market = this.market(symbol);
        Int64? maxLimit = 1000;
        Int64? configuredLimit = this.safeInteger(this.safeDict(this.options, "fetchOHLCV", new Dictionary<string, object>() {}), "limit");
        if ((configuredLimit != null))
        {
            maxLimit = configuredLimit;
        }
        Int64? requestLimit = maxLimit;
        if ((limit != null))
        {
            requestLimit = Math.Min(limit.Value, maxLimit.GetValueOrDefault());
        }
        int duration = this.parseTimeframe(timeframeVar);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "conid", (market.ContainsKey("id") ? market["id"] : null) },
            { "bar", this.safeString(this.timeframes, timeframeVar, timeframeVar) },
        };
        if ((since != null))
        {
            // startTime is exclusive, the first returned bar opens strictly after it, so the request starts one bar earlier
            // and the extra leading bar is removed by filterBySinceLimit in parseOHLCVs
            request["startTime"] = this.ibkrFormatTime((since - (duration * 1000L)));
            request["direction"] = "1"; // forward from startTime, by default startTime is the end of the range
            if ((limit != null))
            {
                if ((limit < maxLimit))
                {
                    requestLimit = (limit + 1);
                }
            }
        }
        request["period"] = this.ibkrPeriod(duration, requestLimit);
        Dictionary<string, object> response = await this.webapiGetV1ApiIserverMarketdataHistory(this.extend(request, parameters));
        //
        //     {
        //         "points": 99,
        //         "startTime": "20261007-18:20:00",
        //         "data": [
        //             { "o": 336.94, "c": 336.89, "h": 336.97, "l": 336.85, "v": 1164.625, "t": 1791397200000 }
        //         ],
        //         ...
        //     }
        //
        List<object> data = this.safeList(response, "data", new List<object>() {});
        return ccxt.BaseExchange.ToOHLCVList(this.parseOHLCVs(data, market,timeframeVar, since, limit));
    }

    public virtual string? ibkrPeriod(Int64 duration, Int64? limit)
    {
        // duration of one bar in seconds, the period is expressed in the largest fitting unit
        Int64? total = (duration * limit);
        if ((duration < 3600))
        {
            return (this.numberToString(this.parseToInt(((double?)total / 60))) + "min");
        } else if ((duration < 86400))
        {
            return (this.numberToString(this.parseToInt(((double?)total / 3600))) + "h");
        } else if ((duration < 604800))
        {
            return (this.numberToString(this.parseToInt(((double?)total / 86400))) + "d");
        } else if ((duration < 2592000))
        {
            return (this.numberToString(this.parseToInt(((double?)total / 604800))) + "w");
        }
        // monthly bars, long month periods (e.g. "1000m") are rejected with "Chart data unavailable", so they are expressed in years
        Int64? months = this.parseToInt(((double?)total / 2592000));
        if ((months == null || months <= 12))
        {
            return (this.numberToString(months) + "m");
        }
        Int64 years = Math.Min(this.parseToInt(((double?)((months + 11)) / 12)).GetValueOrDefault(), 15); // 15y is the documented maximum period
        return (this.numberToString(years) + "y");
    }

    public virtual string? ibkrFormatTime(object timestamp)
    {
        // YYYYMMDD-hh:mm:ss in UTC
        string iso = ((string)this.iso8601(timestamp));
        return ((this.yyyymmdd(timestamp, "") + "-") + ((iso == null) ? null : iso.Substring(Math.Min(11, iso.Length), Math.Min(19, iso.Length) - Math.Min(11, iso.Length))));
    }

    public override IList<object> parseOHLCV(object ohlcv, IDictionary<string, object> market = null)
    {
        return new List<object> {this.safeInteger(ohlcv, "t"), this.safeNumber(ohlcv, "o"), this.safeNumber(ohlcv, "h"), this.safeNumber(ohlcv, "l"), this.safeNumber(ohlcv, "c"), this.safeNumber(ohlcv, "v")};
    }

    /**
     * @method
     * @name interactivebrokers#fetchAccounts
     * @description fetch all the accounts associated with a profile
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-all-accounts
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.method] 'privateGetPortfolioAccounts' (default) or 'privateGetPortfolioSubaccounts'
     * @returns {object[]} a list of [account structures]{@link https://docs.ccxt.com/?id=account-structure}
     */
    public async override Task<List<ccxt.Account>> FetchAccounts(IDictionary<string, object> parameters = null)
    {
        // as required by IBKR, iserver/accounts must be called at least once before any other trading endpoint
        parameters ??= new Dictionary<string, object>();
        List<object> portfolioAccounts = await this.fetchPortfolioAccounts(parameters);
        Dictionary<string, object> accountsById = this.indexBy(portfolioAccounts, "accountId");
        List<object> accountIds = new List<object>(accountsById.Keys);
        int length = accountIds.Count;
        if ((length == 0))
        {
            throw new ExchangeError ("No tradingaccount IDs found for the user") ;
        }
        if ((this.safeString(this.options, "accountId") == null))
        {
            if ((length == 1))
            {
                this.options["accountId"] = (accountIds != null && 0 < accountIds.Count ? accountIds[0] : null);
            } else
            {
                throw new ExchangeError (("Multiple account IDs found, please set .options[\"accountId\"] to desired one from: " + String.Join(", ", accountIds.ToArray()))) ;
            }
        }
        List<object> accounts = new List<object>() {};
        for (int i = 0; i < (portfolioAccounts?.Count ?? 0); i++)
        {
            accounts.Add(this.parseAccount(this.extend(new Dictionary<string, object>() {}, portfolioAccounts[i])));
        }
        return ccxt.BaseExchange.ToAccountList(accounts);
    }

