    /**
     * @method
     * @name interactivebrokers#fetchOrder
     * @description fetches information on an order made by the user, only orders of the current brokerage session are available
     * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/get-order-status
     * @param {string} id the order id
     * @param {string} [symbol] unified symbol of the market the order was made in
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public async override Task<ccxt.Order> FetchOrder(string id, string symbol = null, IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.authenticate();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        IDictionary<string, object> market = null;
        if ((symbol != null))
        {
            market = this.market(symbol);
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "orderId", id },
        };
        Dictionary<string, object> response = null;
        try
        {
            response = await this.webapiGetV1ApiIserverAccountOrderStatusOrderId(this.extend(request, parameters));
        } catch(Exception ex)
        {
            if (ex is InvalidProxySettings)
            {
                throw ex;
            }
            if (ex is OperationFailed)
            {
                throw ex;
            }
            string? message = ((string)this.exceptionMessage(ex));
            // eg:  {"error":"Order 54348392 is not found","statusCode":503}
            if ((message?.IndexOf("is not found", StringComparison.Ordinal) ?? -1) >= 0)
            {
                string newMessage = ((("Order with id " + id) + " is not found, however it might be just because the time threshold has been passed for that order retrieval. Original message: ") + message);
                throw new OrderNotFound (newMessage) ;
            } else
            {
                throw new InvalidOrder (message) ;
            }
        }
        if ((response == null))
        {
            throw new NullResponse ((this.id + " fetchOrder() returned empty response")) ;
        }
        return this.parseOrder(this.extend(new Dictionary<string, object>() {}, response), market);
    }

