     * @param {int} [limit] the maximum number of order structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.filters] an exchange-side status filter, by default all orders are fetched and filtered by their unified status
     * @param {boolean} [params.force] refresh the cached order list first, default true
     * @returns {Order[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public async override Task<List<ccxt.Order>> FetchCanceledAndClosedOrders(string symbol = null, Int64? since = null, Int64? limit = null, IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.authenticate();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        IDictionary<string, object> market = null;
        if ((symbol != null))
        {
            market = this.market(symbol);
        }
        List<object> orders = await this.fetchLiveOrdersRaw(parameters);
        IList<object> parsed = ccxt.BaseExchange.FromOrderList(this.parseOrders(orders, market, null, null));
        List<object> result = new List<object>() {};
