    public virtual string? parseOrderStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "Inactive", "rejected" },
            { "PendingSubmit", "open" },
            { "PreSubmitted", "open" },
            { "Presubmitted", "open" },
            { "Submitted", "open" },
            { "Filled", "closed" },
            { "PendingCancel", "open" },
            { "PreCancelled", "canceled" },
            { "Cancelled", "canceled" },
            { "WarnState", "open" },
        };
        return this.safeString(statuses, status, status);
    }

    public virtual string? parseOrderType(string? orderType)
    {
        if ((orderType == null))
        {
            return null;
        }
        Dictionary<string, object> types = new Dictionary<string, object>() {
            { "LMT", "limit" },
            { "LIMIT", "limit" },
            { "MKT", "market" },
            { "MARKET", "market" },
            { "STP", "market" },
            { "STOP", "market" },
            { "STP LMT", "limit" },
            { "STOP_LIMIT", "limit" },
            { "STOPLIMIT", "limit" },
            { "TRAIL", "market" },
            { "TRAILLMT", "limit" },
            { "TRAILING_STOP", "market" },
            { "TRAILING_STOP_LIMIT", "limit" },
            { "MIDPRICE", "limit" },
        };
        return this.safeString(types, orderType.ToUpper(), orderType);
    }

