            string datetime = (((((((((((("20" + ((orderTime == null) ? null : orderTime.Substring(0, Math.Min(2, orderTime.Length)))) + "-") + ((orderTime == null) ? null : orderTime.Substring(Math.Min(2, orderTime.Length), Math.Min(4, orderTime.Length) - Math.Min(2, orderTime.Length)))) + "-") + ((orderTime == null) ? null : orderTime.Substring(Math.Min(4, orderTime.Length), Math.Min(6, orderTime.Length) - Math.Min(4, orderTime.Length)))) + "T") + ((orderTime == null) ? null : orderTime.Substring(Math.Min(6, orderTime.Length), Math.Min(8, orderTime.Length) - Math.Min(6, orderTime.Length)))) + ":") + ((orderTime == null) ? null : orderTime.Substring(Math.Min(8, orderTime.Length), Math.Min(10, orderTime.Length) - Math.Min(8, orderTime.Length)))) + ":") + ((orderTime == null) ? null : orderTime.Substring(Math.Min(10, orderTime.Length), Math.Min(12, orderTime.Length) - Math.Min(10, orderTime.Length)))) + "Z");
            timestamp = this.parse8601(datetime);
